Let $(\mathcal{Q}, d)$ be a metric space.
	Let $y,z,q,p\in\mathcal{Q}$. Assume
	\begin{equation*}
		\overline{y,q}^2 - \overline{y,p}^2 - \overline{z,q}^2 + \overline{z,p}^2 \leq 2 \, \overline{q,p}\, \overline{y,z}
		\, .
	\end{equation*}
	Let $\tau\colon[0,\infty)\to\mathbb{R}$ be differentiable. Assume $\tau$ is nondecreasing, convex and has a concave derivative $\tau^\prime$. Then
	\begin{equation}
		\tau(\overline{y,q})  - \tau(\overline{y,p}) - \tau(\overline{z,q}) + \tau(\overline{z,p}) \leq 2 \, \overline{q,p} \, \tau^\prime(\overline{y,z})\, .
	\end{equation}

Let $\tau\in\mathcal{S}$.  Let $(\mathcal{Q}, d)$ be a metric space.
	Let $y,z,q,p\in\mathcal{Q}$. Assume, there is $L_{}\in[2,\infty)$ such that
	\begin{equation}
		\overline{y,q}^2 - \overline{y,p}^2 - \overline{z,q}^2 + \overline{z,p}^2 \leq L_{} \, \overline{q,p}\, \overline{y,z}
		\, .
	\end{equation}
	Then
	\begin{equation}
		\tau(\overline{y,q})  - \tau(\overline{y,p}) - \tau(\overline{z,q}) + \tau(\overline{z,p}) \leq L_{} \, \overline{q,p} \, \tau^\prime\!\left( \overline{y,z} \right)\, .
	\end{equation}

Let $\tau\in\mathcal{S}_0^{3}$.
	\begin{enumerate}[label=(\roman*)]
		\item 
		For all $a,b,c\in[0, \infty)$, $s\in [-1, \min(1, 2\frac ac -1)]$, we have
		\begin{equation}
			\tau(a) - \tau(c) -\tau(\left| a-b \right|) + \tau_{\!\sqrt{}}(c^2 - 2scb + b^2) \leq 2b \tau^\prime(a-sc)\
			\, .
		\end{equation}
		\item 
		For all $a,b,c\in[0, \infty)$ with $a\geq c$, we have
		\begin{equation}
			\tau(a) - \tau(c) -\tau_{\!\sqrt{}}((a-b)^2 - 4bc) + \tau_{\!\sqrt{}}(b + c) \leq 2b \tau^\prime(a-c)
			\, .
		\end{equation}
	\end{enumerate}

Let $\tau\in\mathcal{S}_0^{3}$.
	Let $a,b,c\in[0, \infty)$. Assume $a\geq c$. Then
	\begin{equation}
		\tau(a) - \tau(c) -\tau_{\!\sqrt{}}((a-b)^2 - 4bc) + \tau_{\!\sqrt{}}(b + c) \leq 2b \tau^\prime(a-c)
		\, .
	\end{equation}
